#include "fs_utils.h"
#include <iostream>
static bool parse_mkdir(std::vector<std::string>&p,std::string&path,bool&r){for(size_t i=1;i<p.size();++i){std::string n,v;if(p[i].find('=')==std::string::npos){if(minusculas(p[i])=="r"){r=true;continue;}std::cout<<"[ERROR] MKDIR: -r no recibe valor\n";return false;}if(!dividir_parametro(p[i],n,v)){return false;}n=minusculas(n);if(n=="path")path=v;else{std::cout<<"[ERROR] Parametro no reconocido: -"<<n<<"\n";return false;}}return !path.empty();}
void mkdir_cmd(std::vector<std::string>&p,EstadoGlobal&e){if(!e.sesionActiva){std::cout<<"[ERROR] No existe una sesion activa\n";return;}std::string path;bool rec=false;if(!parse_mkdir(p,path,rec)){std::cout<<"[ERROR] MKDIR requiere -path\n";return;}if(path=="/"){std::cout<<"[ERROR] La raiz ya existe\n";return;}UbicacionParticion part;if(!abrir_particion_por_sesion(e,part)){std::cout<<"[ERROR] Particion de sesion no disponible\n";return;}FILE*f=fopen(part.ruta.c_str(),"r+b");if(!f){std::cout<<"[ERROR] No se pudo abrir disco\n";return;}sbloque sb;if(!leer_super(f,part,sb)){fclose(f);return;}int existing;if(resolver_path(f,sb,path,existing)){fclose(f);std::cout<<"[ERROR] La carpeta ya existe\n";return;}auto parts=componentes_path(path);int current=0;for(size_t i=0;i<parts.size();++i){int child;if(buscar_en_directorio(f,sb,current,parts[i],child)){inodo ci;leer_inodo(f,sb,child,ci);if(ci.i_type!='0'){fclose(f);std::cout<<"[ERROR] Existe un archivo con ese nombre\n";return;}current=child;continue;}if(i+1<parts.size()&&!rec){fclose(f);std::cout<<"[ERROR] No existen las carpetas padre. Use -r\n";return;}inodo parent;leer_inodo(f,sb,current,parent);if(!permiso_inodo(e,parent,2)){fclose(f);std::cout<<"[ERROR] Sin permiso de escritura en la carpeta padre\n";return;}int ni;if(!crear_directorio(f,sb,current,parts[i],std::stoi(e.sesion.id_user),std::stoi(e.sesion.id_grp),664,ni)){fclose(f);std::cout<<"[ERROR] No se pudo crear la carpeta (sin espacio o nombre invalido)\n";return;}current=ni;}escribir_super(f,sb);fclose(f);std::cout<<"[EXITOSO] Directorio creado: "<<path<<"\n";}
